tool_input.new_string:
handleVisibleChange(visible) {
  this.$emit('visible-change', visible)
  // 每次展开重置定位记忆，收起时清空，避免上次会话的定位影响本次
  this.lastPopperPlacement = null
  if (!visible) {
    this.unbindPopperWindowEvents()
    this.clearPopperSyncTimers()
    return
  }
  this.bindPopperWindowEvents()
  this.schedulePopperSync()
},

syncPopperStyle() {
  this.$nextTick(() => {
    requestAnimationFrame(() => {
      const select = /** @type {any} */ (this.$refs.elSelect)
      const popper = select?.popperElm
      const rect = select?.$el?.getBoundingClientRect?.()
      const selectWidth = Math.ceil(select?.$el?.getBoundingClientRect?.().width || 0)
      if (!popper || !rect) return

      if (selectWidth > 0) {
        popper.style.minWidth = `${selectWidth}px`
        popper.style.width = `${selectWidth}px`
      }

      const maxLayerZIndex = this.getMaxLayerZIndex()
      if (maxLayerZIndex > 0) {
        popper.style.zIndex = `${maxLayerZIndex + 10}`
      }

      if (typeof select.updatePopper === 'function') {
        select.updatePopper()
      }

      const popperHeight = Math.ceil(popper.getBoundingClientRect?.().height || popper.offsetHeight || 0)
      // 下拉尚未完成布局（高度为 0）时不要定位，避免先落到错误位置再被后续定时器纠正而可见跳动
      if (popperHeight <= 0) return

      const gap = 4
      const canPlaceAbove = rect.top > popperHeight + gap
      const placeAbove = window.innerHeight - rect.bottom < popperHeight + gap && canPlaceAbove
      const top = placeAbove
        ? Math.max(rect.top - popperHeight - gap, gap)
        : Math.max(Math.min(rect.bottom + gap, window.innerHeight - popperHeight - gap), gap)
      const left = Math.max(rect.left, gap)

      // 去抖关键：若本次定位与上次已落地定位在 1px 内一致，则不再重写 inline style。
      // 原实现每次(0/32/80/160/320ms)都强制重排 position/top/left，测高变化会让下拉在
      // 上下翻位之间来回跳（视觉即「抖动」）。记忆上次定位后，一旦稳定就保持不动。
      const last = this.lastPopperPlacement
      if (
        last &&
        last.position === 'fixed' &&
        Math.abs(last.top - top) < 1 &&
        Math.abs(last.left - left) < 1
      ) {
        return
      }

      popper.style.position = 'fixed'
      popper.style.left = `${left}px`
      popper.style.top = `${top}px`
      popper.style.transform = 'none'
      popper.style.margin = '0'
      this.lastPopperPlacement = { position: 'fixed', top, left }
    })
  })
}

